def main():
    archive = base64.b64decode(PAYLOAD, validate=True)
    if hashlib.sha256(archive).hexdigest() != SHA256:
        raise SystemExit("Installer payload is damaged")
    with tempfile.TemporaryDirectory(prefix="forged-installer-") as temporary:
        root = Path(temporary)
        with zipfile.ZipFile(io.BytesIO(archive)) as bundle:
            for item in bundle.infolist():
                path = PurePosixPath(item.filename)
                if path.is_absolute() or ".." in path.parts or item.file_size > 2_000_000:
                    raise SystemExit("Invalid embedded installer file")
                destination = root.joinpath(*path.parts)
                destination.parent.mkdir(parents=True, exist_ok=True)
                destination.write_bytes(bundle.read(item))
        return subprocess.run([sys.executable, str(root / "install-arch.py"), *sys.argv[1:]], check=False).returncode


if __name__ == "__main__":
    raise SystemExit(main())
